func NewExecutor(config *Config, overrides map[string]string) *Executor {
    return &Executor{
        config:     config,
        globals:    config.globalParams(overrides),
        status:     map[string]string{},
        results:    map[string]*StageResult{},
        outputs:    map[string]map[string]string{},
        values:     map[string]map[string]*ArtifactValue{},
        meta:       map[string]*ArtifactMeta{},
        cacheKeys:  map[string]string{},
        cacheStats: &CacheStats{},
    }
}

func (e *Executor) Run() (*RunOutput, error) {
    valid, errs := e.config.Validate()
    if !valid {
        return nil, fmt.Errorf("%s", strings.Join(errs, "; "))
    }
    order, err := e.config.topologicalOrder()
    if err != nil {
        return nil, err
    }

    runArtifacts := map[string]*ArtifactOutput{}

    for _, name := range order {
        stage, _ := e.config.stageByName(name)
        e.outputs[name] = map[string]string{}
        e.values[name] = map[string]*ArtifactValue{}
        e.results[name] = &StageResult{Status: "pending", Outputs: map[string]string{}}

        skip := false
        for _, dep := range stage.DependsOn {
            if e.status[dep] != "success" {
                skip = true
                break
            }
        }
        if skip {
            e.status[name] = "skipped"
            e.results[name].Status = "skipped"
            continue
        }

        inputValues, inputIDs, err := e.resolveInputs(stage)
        if err != nil {
            e.status[name] = "failed"
            e.results[name].Status = "failed"
            e.results[name].Error = err.Error()
            continue
        }

        params := e.config.stageParams(name, e.globals)
        inputKeys := e.inputCacheKeys(stage)
        cacheKey, keyErr := computeCacheKey(stage, params, inputKeys, -1)
        if keyErr != nil {
            e.status[name] = "failed"
            e.results[name].Status = "failed"
            e.results[name].Error = keyErr.Error()
            continue
        }
        e.cacheKeys[name] = cacheKey

        var out map[string]*ArtifactValue
        start := time.Now()
        if !e.noCache && cacheEntryExists(cacheKey) {
            loaded, err := loadCacheEntry(cacheKey)
            duration := time.Since(start).Milliseconds()
            e.results[name].DurationMs = duration
            if err == nil {
                out = loaded
                e.results[name].CacheHit = true
                e.cacheStats.Hits++
            } else {
                e.cacheStats.Misses++
                out, err = executeStage(stage, params, inputValues)
                duration = time.Since(start).Milliseconds()
                e.results[name].DurationMs = duration
                if err != nil {
                    e.status[name] = "failed"
                    e.results[name].Status = "failed"
                    e.results[name].Error = err.Error()
                    continue
                }
            }
        } else {
            var err error
            out, err = executeStage(stage, params, inputValues)
            duration := time.Since(start).Milliseconds()
            e.results[name].DurationMs = duration
            if err != nil {
                e.status[name] = "failed"
                e.results[name].Status = "failed"
                e.results[name].Error = err.Error()
                continue
            }
            if !e.noCache {
                _ = saveCacheEntry(cacheKey, name, stage.Type, out)
            }
            e.cacheStats.Misses++
        }

        e.status[name] = "success"
        e.results[name].Status = "success"
        ts := time.Now().UnixNano()

        for port, val := range out {
            id := artifactID(e.config.Pipeline.Name, name, port, ts)
            e.values[name][port] = val
            e.outputs[name][port] = id
            typ := val.Type()
            summary := val.Summary()
            meta := &ArtifactMeta{
                ID:        id,
                Stage:     name,
                Port:      port,
                Type:      typ,
                Summary:   summary,
                Inputs:    inputIDs,
                Outputs:   []string{},
                Timestamp: ts,
            }
            e.meta[id] = meta
            for _, inID := range inputIDs {
                if parent, ok := e.meta[inID]; ok {
                    parent.Outputs = appendUnique(parent.Outputs, id)
                }
            }
            runArtifacts[id] = &ArtifactOutput{Stage: name, Port: port, Type: typ, Summary: summary}
        }
    }

    status := "success"
    for _, s := range e.results {
        if s.Status != "success" {
            status = "failed"
            break
        }
    }

    run := &RunOutput{
        Pipeline:   e.config.Pipeline.Name,
        Status:     status,
        Stages:     e.results,
        Artifacts:  runArtifacts,
        CacheStats: e.cacheStats,
    }

    if err := saveArtifacts(e.meta); err != nil {
        return nil, err
    }
    if err := saveRun(run); err != nil {
        return nil, err
    }

    return run, nil
}

func (e *Executor) inputCacheKeys(stage *StageConfig) map[string]string {
    keys := map[string]string{}
    for local, ref := range stage.Inputs {
        parts := strings.SplitN(ref, ".", 2)
        if len(parts) != 2 {
            continue
        }
        depStage := parts[0]
        if key, ok := e.cacheKeys[depStage]; ok {
            keys[local] = key
        }
    }
    return keys
}

func (e *Executor) resolveInputs(stage *StageConfig) (map[string]*ArtifactValue, []string, error) {
    inputs := map[string]*ArtifactValue{}
    ids := []string{}
    for local, ref := range stage.Inputs {
        parts := strings.SplitN(ref, ".", 2)
        if len(parts) != 2 {
            return nil, nil, fmt.Errorf("stage %q has invalid input reference %q", stage.Name, ref)
        }
        depStage, port := parts[0], parts[1]
        id, ok := e.outputs[depStage][port]
        if !ok {
            return nil, nil, fmt.Errorf("stage %q input %q references unavailable output %s.%s", stage.Name, local, depStage, port)
        }
        val, ok := e.values[depStage][port]
        if !ok || val == nil {
            return nil, nil, fmt.Errorf("stage %q input %q references unavailable artifact %s.%s", stage.Name, local, depStage, port)
        }
        inputs[local] = val
        ids = append(ids, id)
    }
    return inputs, ids, nil
}

func executeStage(stage *StageConfig, params map[string]interface{}, inputs map[string]*ArtifactValue) (map[string]*ArtifactValue, error) {
    switch stage.Type {
    case "data-source":
        return executeDataSource(stage, params, inputs)
    case "transform":
        return executeTransform(stage, params, inputs)
    case "split":
        return executeSplit(stage, params, inputs)
    case "train":
        return executeTrain(stage, params, inputs)
    case "evaluate":
        return executeEvaluate(stage, params, inputs)
    case "register":
        return executeRegister(stage, params, inputs)
    }
    return nil, fmt.Errorf("unknown stage type %q", stage.Type)
}

func executeDataSource(stage *StageConfig, params map[string]interface{}, inputs map[string]*ArtifactValue) (map[string]*ArtifactValue, error) {
    path, ok := getString(params, "path")
    if !ok {
        return nil, fmt.Errorf("data-source stage %q requires path", stage.Name)
    }
    schema, _ := getMap(params, "schema")
    ds, err := loadDataset(path, schema)
    if err != nil {
        return nil, err
    }
    return map[string]*ArtifactValue{"data": {Dataset: ds}}, nil
}

func (c *Config) topologicalOrder() ([]string, error) {
    indeg := map[string]int{}
    adj := map[string][]string{}
    for _, s := range c.Stages {
        indeg[s.Name] = 0
    }
    for _, s := range c.Stages {
        for _, dep := range s.DependsOn {
            if _, ok := c.stageByName(dep); ok {
                adj[dep] = append(adj[dep], s.Name)
                indeg[s.Name]++
            }
        }
    }
    queue := []string{}
    for _, s := range c.Stages {
        if indeg[s.Name] == 0 {
            queue = append(queue, s.Name)
        }
    }
    order := []string{}
    for len(queue) > 0 {
        node := queue[0]
        queue = queue[1:]
        order = append(order, node)
        for _, next := range adj[node] {
            indeg[next]--
            if indeg[next] == 0 {
                queue = append(queue, next)
            }
        }
    }
    if len(order) < len(c.Stages) {
        if cycle, ok := c.detectCycle(); ok && len(cycle) > 0 {
            return nil, fmt.Errorf("cycle detected involving stages: %s", strings.Join(cycle, ", "))
        }
        return nil, fmt.Errorf("cycle detected involving stages: %s", joinStageNames(c.Stages))
    }
    return order, nil
}

func joinStageNames(stages []StageConfig) string {
    names := []string{}
    for _, s := range stages {
        names = append(names, s.Name)
    }
    return strings.Join(names, ", ")
}

func artifactID(pipeline, stage, port string, ts int64) string {
    if pipeline == "" {
        pipeline = "pipeline"
    }
    return fmt.Sprintf("%s-%s-%s-%d", pipeline, stage, port, ts)
}

func (v *ArtifactValue) Type() string {
    if v.Dataset != nil {
        return "dataset"
    }
    if v.Model != nil {
        return "model"
    }
    if v.Report != nil {
        return "report"
    }
    if v.Entry != nil {
        return "entry"
    }
    return "unknown"
}

func (v *ArtifactValue) Summary() map[string]interface{} {
    if v.Dataset != nil {
        return v.Dataset.Summary()
    }
    if v.Model != nil {
        return map[string]interface{}{
            "algorithm":   v.Model.Algorithm,
            "target":      v.Model.Target,
            "features":    v.Model.Features,
            "hyperparams": v.Model.Hyperparams,
        }
    }
    if v.Report != nil {
        return v.Report.Summary()
    }
    if v.Entry != nil {
        return map[string]interface{}{
            "name":    v.Entry.Name,
            "version": v.Entry.Version,
            "stage":   v.Entry.Stage,
        }
    }
    return map[string]interface{}{}
}

func inputDataset(inputs map[string]*ArtifactValue) *Dataset {
    for _, in := range inputs {
        if in != nil && in.Dataset != nil {
            return in.Dataset
        }
    }
    return nil
}

func appendUnique(s []string, v string) []string {
    for _, x := range s {
        if x == v {
            return s
        }
    }
    return append(s, v)
}

func artifactsPath() string {
    return filepath.Join(".mlpipe", "artifacts.json")
}

func loadArtifacts() (map[string]*ArtifactMeta, error) {
    data, err := os.ReadFile(artifactsPath())
    if err != nil {
        if os.IsNotExist(err) {
            return map[string]*ArtifactMeta{}, nil
        }
        return nil, err
    }
    var m map[string]*ArtifactMeta
    if err := json.Unmarshal(data, &m); err != nil {
        return nil, err
    }
    if m == nil {
        m = map[string]*ArtifactMeta{}
    }
    return m, nil
}

func saveArtifacts(newMeta map[string]*ArtifactMeta) error {
    existing, err := loadArtifacts()
    if err != nil {
        return err
    }
    for k, v := range newMeta {
        existing[k] = v
    }
    if err := os.MkdirAll(".mlpipe", 0755); err != nil {
        return err
    }
    data, err := json.MarshalIndent(existing, "", "  ")
    if err != nil {
        return err
    }
    return os.WriteFile(artifactsPath(), data, 0644)
}

func saveRun(run *RunOutput) error {
    dir := filepath.Join(".mlpipe", "runs")
    if err := os.MkdirAll(dir, 0755); err != nil {
        return err
    }
    name := safeFileName(run.Pipeline)
    if name == "" {
        name = "pipeline"
    }
    path := filepath.Join(dir, fmt.Sprintf("%s-%d.json", name, time.Now().UnixNano()))
    data, err := json.MarshalIndent(run, "", "  ")
    if err != nil {
        return err
n    }
    return os.WriteFile(path, data, 0644)
}

func safeFileName(s string) string {
    if s == "" {
        return "pipeline"
    }
    return strings.Map(func(r rune) rune {
        if r == '/' || r == '\\' || r == ':' || r == ' ' {
            return '_'
        }
        return r
    }, s)
}

func queryLineage(id string, direction string) (map[string]interface{}, error) {
    artifacts, err := loadArtifacts()
    if err != nil {
        return nil, err
    }
    if _, ok := artifacts[id]; !ok {
        return nil, fmt.Errorf("artifact not found: %s", id)
    }

    set := map[string]bool{}
    switch direction {
    case "up":
        collectAncestors(id, artifacts, set)
    case "down":
        collectDescendants(id, artifacts, set)
    case "both":
        set[id] = true
        collectBoth(id, artifacts, set)
    default:
        return nil, fmt.Errorf("invalid direction %q", direction)
    }

    ids := []string{}
    for k := range set {
        ids = append(ids, k)
    }
    sort.Slice(ids, func(i, j int) bool {
        a := artifacts[ids[i]]
        b := artifacts[ids[j]]
        if a.Timestamp != b.Timestamp {
            return a.Timestamp < b.Timestamp
        }
        return ids[i] < ids[j]
    })

    lineage := []map[string]interface{}{}
    for _, aid := range ids {
        m := artifacts[aid]
        inputs := m.Inputs
        outputs := m.Outputs
        if inputs == nil {
            inputs = []string{}
        }
        if outputs == nil {
            outputs = []string{}
        }
        lineage = append(lineage, map[string]interface{}{
            "id":        m.ID,
            "stage":     m.Stage,
            "port":      m.Port,
            "type":      m.Type,
            "summary":   m.Summary,
            "inputs":    inputs,
            "outputs":   outputs,
            "timestamp": m.Timestamp,
        })
    }
    return map[string]interface{}{"artifacts": lineage}, nil
}

func collectAncestors(id string, artifacts map[string]*ArtifactMeta, set map[string]bool) {
    m, ok := artifacts[id]
    if !ok {
        return
    }
    for _, in := range m.Inputs {
        if !set[in] {
            set[in] = true
            collectAncestors(in, artifacts, set)
        }
    }
}

func collectDescendants(id string, artifacts map[string]*ArtifactMeta, set map[string]bool) {
    m, ok := artifacts[id]
    if !ok {
        return
    }
    for _, out := range m.Outputs {
        if !set[out] {
            set[out] = true
            collectDescendants(out, artifacts, set)
        }
    }
}

func collectBoth(id string, artifacts map[string]*ArtifactMeta, set map[string]bool) {
    m, ok := artifacts[id]
    if !ok {
        return
    }
    for _, in := range m.Inputs {
        if !set[in] {
            set[in] = true
            collectBoth(in, artifacts, set)
        }
    }
    for _, out := range m.Outputs {
        if !set[out] {
            set[out] = true
            collectBoth(out, artifacts, set)
        }
    }
}
