    splitName, _ := e.config.splitStageName()
    postSplit := e.config.postSplitStages(splitName)
    preSplitOrder := []string{}
    postSplitOrder := []string{}
    for _, name := range order {
        if postSplit[name] {
            postSplitOrder = append(postSplitOrder, name)
        } else {
            preSplitOrder = append(preSplitOrder, name)
