    for _, fm := range foldMetrics {
        for name := range fm {
            metricNames[name] = true
        }
    }
    for name := range metricNames {
        perFold := make([]float64, e.cvFolds)
        sum := 0.0
        count := 0
        for i, fm := range foldMetrics {
            if v, ok := fm[name]; ok {
                perFold[i] = v
                sum += v
                count++
            } else {
                perFold[i] = 0.0
            }
        }
        mean := 0.0
        if count > 0 {
            mean = sum / float64(count)
        }
        variance := 0.0
        for _, v := range perFold {
            d := v - mean
            variance += d * d
        }
        variance /= float64(e.cvFolds)
        cvMetrics[name] = CVMetricAgg{
            Mean:    mean,
            Std:     math.Sqrt(variance),
            PerFold: perFold,
        }
    }

    status := "success"
    for _, r := range e.results {
        if r.Status != "success" {
            status = "failed"
            break
        }
    }
    for _, fr := range foldResults {
        if fr.Status != "success" {
            status = "failed"
            break
        }
    }

    run := &CVRunOutput{
        Pipeline:    e.config.Pipeline.Name,
        Status:      status,
        CVFolds:     e.cvFolds,
        Stages:      e.results,
        FoldResults: foldResults,
        CVResults:   CVResults{Metrics: cvMetrics},
        Artifacts:   allArtifacts,
        CacheStats:  e.cacheStats,
    }

    if err := saveArtifacts(e.meta); err != nil {
        return nil, err
    }
    if err := saveRunAny(run); err != nil {
        return nil, err
    }
    return run, nil
}

func (e *Executor) executeStageCached(name string, fold, k int, runArtifacts map[string]*ArtifactOutput) bool {
    stage, _ := e.config.stageByName(name)
    e.outputs[name] = map[string]string{}
    e.values[name] = map[string]*ArtifactValue{}
    e.results[name] = &StageResult{Status: "pending", Outputs: map[string]string{}}

    skip := false
    for _, dep := range stage.DependsOn {
        if e.status[dep] != "success" {
            skip = true
            break
        }
    }
    if skip {
        e.status[name] = "skipped"
        e.results[name].Status = "skipped"
        return false
    }

    inputValues, inputIDs, err := e.resolveInputs(stage)
    if err != nil {
        e.status[name] = "failed"
        e.results[name].Status = "failed"
        e.results[name].Error = err.Error()
        return false
    }

    params := e.config.stageParams(name, e.globals)
    inputKeys := e.inputCacheKeys(stage)
    cacheKey, keyErr := computeCacheKey(stage, params, inputKeys, fold)
    if keyErr != nil {
        e.status[name] = "failed"
        e.results[name].Status = "failed"
        e.results[name].Error = keyErr.Error()
        return false
    }
    e.cacheKeys[name] = cacheKey

    var out map[string]*ArtifactValue
    start := time.Now()
    if !e.noCache && cacheEntryExists(cacheKey) {
        loaded, loadErr := loadCacheEntry(cacheKey)
        if loadErr == nil {
            out = loaded
            e.results[name].CacheHit = true
            e.cacheStats.Hits++
            e.results[name].DurationMs = time.Since(start).Milliseconds()
        } else {
            if !e.noCache {
                e.cacheStats.Misses++
            }
            out, err = e.executeStageForFold(stage, params, inputValues, fold, k)
            e.results[name].DurationMs = time.Since(start).Milliseconds()
            if err != nil {
                e.status[name] = "failed"
                e.results[name].Status = "failed"
                e.results[name].Error = err.Error()
                return false
            }
            if !e.noCache {
                _ = saveCacheEntry(cacheKey, name, stage.Type, out)
            }
        }
    } else {
        out, err = e.executeStageForFold(stage, params, inputValues, fold, k)
        e.results[name].DurationMs = time.Since(start).Milliseconds()
        if err != nil {
            e.status[name] = "failed"
            e.results[name].Status = "failed"
            e.results[name].Error = err.Error()
            return false
        }
        if !e.noCache {
            _ = saveCacheEntry(cacheKey, name, stage.Type, out)
            e.cacheStats.Misses++
        }
    }

    e.status[name] = "success"
    e.results[name].Status = "success"
    ts := time.Now().UnixNano()

    for port, val := range out {
        var id string
        if fold >= 0 {
            id = artifactIDFold(e.config.Pipeline.Name, name, port, ts, fold)
        } else {
            id = artifactID(e.config.Pipeline.Name, name, port, ts)
        }
        e.values[name][port] = val
        e.outputs[name][port] = id
        typ := val.Type()
        summary := val.Summary()
        meta := &ArtifactMeta{
            ID:        id,
            Stage:     name,
            Port:      port,
            Type:      typ,
            Summary:   summary,
            Inputs:    inputIDs,
            Outputs:   []string{},
            Timestamp: ts,
        }
        e.meta[id] = meta
        for _, inID := range inputIDs {
            if parent, ok := e.meta[inID]; ok {
                parent.Outputs = appendUnique(parent.Outputs, id)
            }
        }
        runArtifacts[id] = &ArtifactOutput{Stage: name, Port: port, Type: typ, Summary: summary}
    }
    return true
}

func (e *Executor) executeStageForFold(stage *StageConfig, params map[string]interface{}, inputs map[string]*ArtifactValue, fold, k int) (map[string]*ArtifactValue, error) {
    if stage.Type == "split" && fold >= 0 {
        return executeSplitFold(stage, params, inputs, fold, k)
    }
    if stage.Type == "register" && fold >= 0 {
        execParams := copyParams(params)
        if modelName, ok := getString(execParams, "model_name"); ok {
            execParams["model_name"] = fmt.Sprintf("%s-fold%d", modelName, fold)
        }
        return executeRegister(stage, execParams, inputs)
    }
    return executeStage(stage, params, inputs)
}

func executeSplitFold(stage *StageConfig, params map[string]interface{}, inputs map[string]*ArtifactValue, fold, k int) (map[string]*ArtifactValue, error) {
    ds := inputDataset(inputs)
    if ds == nil {
        return nil, fmt.Errorf("split stage %q requires input data", stage.Name)
    }
    seed, ok := getInt(params, "seed")
    if !ok {
        seed = 0
    }
    stratify, _ := getString(params, "stratify")

    trainRows := []int{}
    testRows := []int{}

    if stratify == "" {
        rng := rand.New(rand.NewSource(int64(seed)))
        perm := rng.Perm(len(ds.Rows))
        for pos, idx := range perm {
            if pos%k == fold {
                testRows = append(testRows, idx)
            } else {
                trainRows = append(trainRows, idx)
            }
        }
    } else {
        idx, ok := ds.ColumnIndex(stratify)
        if !ok {
            return nil, fmt.Errorf("stratify column not found: %s", stratify)
        }
        classes := map[string][]int{}
        for i, row := range ds.Rows {
            val := ""
            if idx < len(row) {
                val = row[idx]
            }
            classes[val] = append(classes[val], i)
        }
        classNames := make([]string, 0, len(classes))
        for c := range classes {
            classNames = append(classNames, c)
        }
        sort.Strings(classNames)
        rng := rand.New(rand.NewSource(int64(seed)))
        for _, c := range classNames {
            rows := classes[c]
            perm := rng.Perm(len(rows))
            for pos, p := range perm {
                srcIdx := rows[p]
                if pos%k == fold {
                    testRows = append(testRows, srcIdx)
                } else {
                    trainRows = append(trainRows, srcIdx)
                }
            }
        }
    }

    train := ds.Copy()
    train.Rows = nil
    test := ds.Copy()
    test.Rows = nil

    appendRow := func(dst *Dataset, src []string) {
        dst.Rows = append(dst.Rows, append([]string{}, src...))
    }
    for _, idx := range trainRows {
        appendRow(train, ds.Rows[idx])
    }
    for _, idx := range testRows {
        appendRow(test, ds.Rows[idx])
    }

    return map[string]*ArtifactValue{"train": {Dataset: train}, "test": {Dataset: test}}, nil
}

func artifactIDFold(pipeline, stage, port string, ts int64, fold int) string {
    if pipeline == "" {
        pipeline = "pipeline"
    }
    return fmt.Sprintf("%s-%s-%s-%d-fold%d", pipeline, stage, port, ts, fold)
}

func copyParams(params map[string]interface{}) map[string]interface{} {
    out := make(map[string]interface{}, len(params))
    for k, v := range params {
        out[k] = v
    }
    return out
}

func copyStringMap(m map[string]string) map[string]string {
    out := make(map[string]string, len(m))
    for k, v := range m {
        out[k] = v
    }
    return out
}

func copyValueMap(m map[string]*ArtifactValue) map[string]*ArtifactValue {
    out := make(map[string]*ArtifactValue, len(m))
    for k, v := range m {
        out[k] = v
    }
    return out
}

func (c *Config) validateCV() error {
    splitNames := []string{}
    for _, s := range c.Stages {
        if s.Type == "split" {
            splitNames = append(splitNames, s.Name)
        }
    }
    if len(splitNames) != 1 {
        return fmt.Errorf("cv mode requires exactly one split stage")
    }
    splitName := splitNames[0]
    post := c.postSplitStages(splitName)

    hasTrain := false
    for name := range post {
        stage, _ := c.stageByName(name)
        if stage != nil && stage.Type == "train" {
            hasTrain = true
        }
    }
    hasEvaluate := false
    for name := range post {
        stage, _ := c.stageByName(name)
        if stage == nil || stage.Type != "evaluate" {
            continue
        }
        ancestors := c.ancestors(name)
        for anc := range ancestors {
            if anc == name {
                continue
            }
            ancStage, ok := c.stageByName(anc)
            if !ok || ancStage.Type != "train" || !post[anc] {
                continue
            }
            hasEvaluate = true
            break
        }
        if hasEvaluate {
            break
        }
    }

    if !hasTrain || !hasEvaluate {
        return fmt.Errorf("cv mode requires train and evaluate stages downstream of the split stage")
    }
    return nil
}

func (c *Config) splitStageName() (string, bool) {
    for _, s := range c.Stages {
        if s.Type == "split" {
            return s.Name, true
        }
    }
    return "", false
}

func (c *Config) stageDeps(s *StageConfig) []string {
    deps := map[string]bool{}
    for _, dep := range s.DependsOn {
        if dep != "" {
            deps[dep] = true
        }
    }
    for _, ref := range s.Inputs {
        parts := strings.SplitN(ref, ".", 2)
        if len(parts) == 2 && parts[0] != "" {
            deps[parts[0]] = true
        }
    }
    out := make([]string, 0, len(deps))
    for dep := range deps {
        out = append(out, dep)
    }
    sort.Strings(out)
    return out
}

func (c *Config) descendants(name string) map[string]bool {
    adj := map[string][]string{}
    for _, s := range c.Stages {
        for _, dep := range c.stageDeps(&s) {
            adj[dep] = append(adj[dep], s.Name)
        }
    }
    set := map[string]bool{}
    var dfs func(n string)
    dfs = func(n string) {
        for _, next := range adj[n] {
            if !set[next] {
                set[next] = true
                dfs(next)
            }
        }
    }
    dfs(name)
    return set
}

func (c *Config) ancestors(name string) map[string]bool {
    deps := map[string][]string{}
    for _, s := range c.Stages {
        deps[s.Name] = c.stageDeps(&s)
    }
    set := map[string]bool{}
    var dfs func(n string)
    dfs = func(n string) {
        for _, dep := range deps[n] {
            if !set[dep] {
                set[dep] = true
                dfs(dep)
            }
        }
    }
    dfs(name)
    return set
}

func (c *Config) postSplitStages(splitName string) map[string]bool {
    post := map[string]bool{splitName: true}
    for name := range c.descendants(splitName) {
        post[name] = true
    }
    return post
}
