            }
            inputTypes[local] = outputPortType(refStage.Type, parts[1])
            edges = append(edges, PlanEdge{From: parts[0], To: name, Port: parts[1]})
        }

        outputTypes := map[string]string{}
        for _, port := range validOutputPorts(stage.Type) {
            outputTypes[port] = outputPortType(stage.Type, port)
        }

        cacheStatus := "unknown"
        phase := (*string)(nil)
