                key, ok := cacheKeys[parts[0]]
                if !ok || key == "" {
                    unknown = true
                    break
                }
                inputKeys[local] = key
            }
            if !unknown {
                key, err := computeCacheKey(stage, params, inputKeys, -1)
                if err == nil {
                    cacheKeys[name] = key
                    if cacheEntryExists(key) {
                        cacheStatus = "hit"
                    } else {
                        cacheStatus = "miss"
                    }
                }
            }
        }

        stages[name] = PlanStage{
            Type:        stage.Type,
            DependsOn:   deps,
            InputTypes:  inputTypes,
            OutputTypes: outputTypes,
            CacheStatus: cacheStatus,
            CVPhase:     phase,
        }
    }

