            return edges[i].From < edges[j].From
        }
        if edges[i].To != edges[j].To {
            return edges[i].To < edges[j].To
        }
        return edges[i].Port < edges[j].Port
    })

    return &PlanOutput{
        Pipeline:      config.Pipeline.Name,
        Mode:          mode,
        CVFolds:       cv,
        ExecutionOrder: executionOrder,
        Stages:        stages,
        Edges:         edges,
    }, nil
